import React, { useState } from 'react';

const VotingPage = () => {
  const [selectedCandidate, setSelectedCandidate] = useState('');
  const [message, setMessage] = useState('');

  const candidates = [
    { id: 1, name: 'Alice Johnson' },
    { id: 2, name: 'Bob Smith' },
    { id: 3, name: 'Charlie Patel' }
  ];

  const handleVoteSubmit = (e) => {
    e.preventDefault();

    if (!selectedCandidate) {
      setMessage('Please select a candidate before submitting.');
      return;
    }

    // This is where blockchain vote logic will go later
    setMessage(`✅ You voted for ${selectedCandidate}`);
  };

  return (
    <div className="container mt-5">
      <h2 className="text-center mb-4">Cast Your Vote</h2>
      <form onSubmit={handleVoteSubmit} className="mx-auto" style={{ maxWidth: '400px' }}>
        {candidates.map((candidate) => (
          <div className="form-check mb-2" key={candidate.id}>
            <input
              className="form-check-input"
              type="radio"
              name="candidate"
              value={candidate.name}
              id={`candidate-${candidate.id}`}
              onChange={(e) => setSelectedCandidate(e.target.value)}
            />
            <label className="form-check-label" htmlFor={`candidate-${candidate.id}`}>
              {candidate.name}
            </label>
          </div>
        ))}
        {message && <div className="alert alert-info mt-3">{message}</div>}
        <button type="submit" className="btn btn-success w-100 mt-3">Submit Vote</button>
      </form>
    </div>
  );
};

export default VotingPage;
